DROP TRIGGER organization_leave_fact ON "${schema}".leave_request;
DROP TRIGGER organization_timesheet_fact ON "${schema}".timesheet_week_batch;
DROP TRIGGER organization_time_entry_fact ON "${schema}".timesheet_entry;
DROP TRIGGER organization_review_fact ON "${schema}".performance_participant;
DROP TRIGGER organization_payroll_version ON "${schema}".payroll_cycle;
DROP TRIGGER organization_payroll_draft_version ON "${schema}".payroll_draft_calculation;
DROP FUNCTION "${schema}".organization_capture_fact();
DROP FUNCTION "${schema}".organization_emit_fact(JSONB,TEXT,BIGINT,UUID,BOOLEAN);
DROP TABLE "${schema}".company_event_outbox;
DROP TABLE "${schema}".organization_review_manager;
DROP TABLE "${schema}".organization_business_actor;
DROP TABLE "${schema}".organization_command_receipt;
DROP TABLE "${schema}".organization_resource_version;
DROP FUNCTION "${schema}".organization_membership_active(UUID,UUID);
DROP FUNCTION "${schema}".organization_reporting_owned(UUID);
DROP FUNCTION "${schema}".organization_reporting_retirement_allowed(UUID);
DROP TABLE "${schema}".organization_fact_bootstrap;
DROP TABLE "${schema}".organization_grant_installation;
ALTER TABLE "${schema}".management_assignment DROP COLUMN graph_version,DROP COLUMN membership_id,DROP COLUMN configuration_hash,DROP COLUMN manager_employee_id;
ALTER TABLE "${schema}".continuous_feedback ALTER COLUMN created_by_user_id SET NOT NULL;
ALTER TABLE "${schema}".loan_posting DROP CONSTRAINT loan_posting_actor_present,DROP COLUMN actor_principal_id,ALTER COLUMN actor_id SET NOT NULL;
ALTER TABLE "${schema}".loan_audit_event DROP CONSTRAINT loan_audit_actor_present,DROP COLUMN actor_principal_id,ALTER COLUMN actor_id SET NOT NULL;
ALTER TABLE "${schema}".payroll_period_input DROP CONSTRAINT payroll_input_actor_present,DROP COLUMN updated_by_principal_id,ALTER COLUMN updated_by SET NOT NULL;
ALTER TABLE "${schema}".payroll_period_input_audit DROP CONSTRAINT payroll_input_audit_actor_present,DROP COLUMN changed_by_principal_id,ALTER COLUMN changed_by SET NOT NULL;
ALTER TABLE "${schema}".payroll_period_adjustment DROP CONSTRAINT payroll_adjustment_actor_present,DROP COLUMN updated_by_principal_id,ALTER COLUMN updated_by SET NOT NULL;
ALTER TABLE "${schema}".payroll_draft_calculation DROP CONSTRAINT payroll_draft_actor_present,DROP COLUMN calculated_by_principal_id,DROP COLUMN finalized_by_principal_id,ALTER COLUMN calculated_by SET NOT NULL;
ALTER TABLE "${schema}".payroll_cycle DROP COLUMN processed_by_principal_id;
